import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import { TodayRecentSection } from './todayRecentOrder'
import { todaySessionMenuLogic } from './todaySessionMenuLogic'
import { todaySpacesLogic } from './todaySpacesLogic'
import { TodayWorkItem } from './todayWorkItems'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todaySessionSelectionLogicValues {
    pinnedItems: TodayWorkItem[] // todaySpacesLogic
    recentGroups: TodayRecentSection[] // todaySpacesLogic
    pendingSessionIds: string[] // todaySessionMenuLogic
    anchorSessionId: string | null
    selectedSessionIds: string[]
    orderedSessionIds: string[]
    visibleSelectedIds: string[]
    batchInProgress: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todaySessionSelectionLogicActions {
    bulkSessionsSettled: (
        updatedIds: string[],
        failedIds: string[]
    ) => {
        failedIds: string[]
        updatedIds: string[]
    } // todaySessionMenuLogic
    clearSelection: () => {
        value: true
    }
    selectRange: (sessionId: string) => {
        sessionId: string
    }
    setSelectedSessionIds: (sessionIds: string[]) => {
        sessionIds: string[]
    }
    toggleSession: (sessionId: string) => {
        sessionId: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todaySessionSelectionLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        orderedSessionIds: (pinnedItems: TodayWorkItem[], recentGroups: TodayRecentSection[]) => string[]
        visibleSelectedIds: (selectedSessionIds: string[], orderedSessionIds: string[]) => string[]
        batchInProgress: (visibleSelectedIds: string[], pendingSessionIds: string[]) => boolean
    }
}

export type todaySessionSelectionLogicType = MakeLogicType<
    todaySessionSelectionLogicValues,
    todaySessionSelectionLogicActions,
    Record<string, any>,
    todaySessionSelectionLogicMeta
>

export const todaySessionSelectionLogic = kea<todaySessionSelectionLogicType>([
    path(['layout', 'today', 'todaySessionSelectionLogic']),
    connect(() => ({
        values: [todaySpacesLogic, ['pinnedItems', 'recentGroups'], todaySessionMenuLogic, ['pendingSessionIds']],
        actions: [todaySessionMenuLogic, ['bulkSessionsSettled']],
    })),
    actions({
        toggleSession: (sessionId: string) => ({ sessionId }),
        selectRange: (sessionId: string) => ({ sessionId }),
        setSelectedSessionIds: (sessionIds: string[]) => ({ sessionIds }),
        clearSelection: true,
    }),
    reducers({
        selectedSessionIds: [
            [] as string[],
            {
                toggleSession: (state, { sessionId }) =>
                    state.includes(sessionId) ? state.filter((id) => id !== sessionId) : [...state, sessionId],
                setSelectedSessionIds: (_, { sessionIds }) => sessionIds,
                clearSelection: () => [],
                // Failed sessions stay selected, so the next click retries only those.
                bulkSessionsSettled: (state, { updatedIds }) => state.filter((id) => !updatedIds.includes(id)),
            },
        ],
        anchorSessionId: [
            null as string | null,
            {
                toggleSession: (_, { sessionId }) => sessionId,
                clearSelection: () => null,
            },
        ],
    }),
    selectors({
        orderedSessionIds: [
            (s) => [s.pinnedItems, s.recentGroups],
            (pinnedItems: TodayWorkItem[], recentGroups: TodayRecentSection[]): string[] => [
                ...new Set(
                    [...pinnedItems, ...recentGroups.flatMap((group) => group.items)]
                        .filter((item) => item.kind === 'session')
                        .map((item) => item.id)
                ),
            ],
        ],
        visibleSelectedIds: [
            (s) => [s.selectedSessionIds, s.orderedSessionIds],
            (selectedSessionIds: string[], orderedSessionIds: string[]): string[] =>
                selectedSessionIds.filter((id) => orderedSessionIds.includes(id)),
        ],
        batchInProgress: [
            (s) => [s.visibleSelectedIds, s.pendingSessionIds],
            (visibleSelectedIds: string[], pendingSessionIds: string[]): boolean =>
                visibleSelectedIds.some((id) => pendingSessionIds.includes(id)),
        ],
    }),
    listeners(({ actions, values }) => ({
        selectRange: ({ sessionId }) => {
            const order = values.orderedSessionIds
            const anchor = values.anchorSessionId
            const from = anchor ? order.indexOf(anchor) : -1
            const to = order.indexOf(sessionId)
            if (from === -1 || to === -1) {
                if (!values.selectedSessionIds.includes(sessionId)) {
                    actions.toggleSession(sessionId)
                }
                return
            }
            const range = order.slice(Math.min(from, to), Math.max(from, to) + 1)
            actions.setSelectedSessionIds([...new Set([...values.selectedSessionIds, ...range])])
        },
    })),
])
